import numpy as np

W1, W2, W3 = W['W1'], W['W2'], W['W3']
L = W1 @ W2 @ W3                    # 500 x 5
Lg = L.reshape(10, 10, 5, 5)        # row, col, channel, action

# up = action 1, down = action 2
T1 = Lg[:, :, 1, 1] - Lg[:, :, 1, 2]   # ch1 (ball) up-down
T4 = Lg[:, :, 4, 1] - Lg[:, :, 4, 2]   # ch4 (prev) up-down

T1i = T1[1:9, 1:9]
T4i = T4[1:9, 1:9]

def corr_shift(A, B, dy, dx):
    Bs = np.roll(B, (dy, dx), axis=(0, 1))
    if dy > 0:
        A2, Bs2 = A[dy:, :], Bs[dy:, :]
    elif dy < 0:
        A2, Bs2 = A[:dy, :], Bs[:dy, :]
    else:
        A2, Bs2 = A, Bs
    if dx > 0:
        A2, Bs2 = A2[:, dx:], Bs2[:, dx:]
    elif dx < 0:
        A2, Bs2 = A2[:, :dx], Bs2[:, :dx]
    return np.corrcoef(A2.flatten(), Bs2.flatten())[0, 1]

print("Zero-shift corr T1 vs T4:", round(corr_shift(T1i, T4i, 0, 0), 3))
best_c, best_s = -2, None
for dy in range(-3, 4):
    for dx in range(-2, 3):
        c = corr_shift(T1i, T4i, dy, dx)
        if c > best_c:
            best_c, best_s = c, (dy, dx)
print("Best shift (dy,dx):", best_s, "corr:", round(best_c, 3))
